// 1. Input Validation
if (!isfinite(wo_config.dt_s) || wo_config.dt_s <= 0.0 ||
    !isfinite(wo_config.prediction_horizon_s) || wo_config.prediction_horizon_s <= 0.0 ||
    !isfinite(wo_config.gain) || wo_config.gain < 0.0 ||
    !isfinite(wo_config.torque_limit) || wo_config.torque_limit <= 0.0 ||
    !isfinite(wo_config.torque_slew) || wo_config.torque_slew <= 0.0 ||
    wo_config.release_rad_s >= wo_config.warn_rad_s ||
    wo_config.warn_rad_s >= wo_config.trip_rad_s ||
    wo_config.minimum_active_cycles < 1 || wo_config.minimum_active_cycles > 100 ||
    wo_config.release_cycles < 1 || wo_config.release_cycles > 100 ||
    wo_config.recovery_cycles < 1 || wo_config.recovery_cycles > 100 ||
    (wo_input.enable != 0 && wo_input.enable != 1) ||
    wo_input.wheels == NULL || wo_input.count != 4) {

    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0;
    wo_output.elapsed = 0;
    wo_output.recovery_count = 0;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for(int i=0; i<4; ++i) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.momentum = (adcs_vec3_t){0,0,0};
    wo_output.torque = (adcs_vec3_t){0,0,0};
    wo_output.momentum_norm = 0.0;
    wo_output.predicted_trip_mask = 0;
    wo_output.saturation_mask = 0;
    wo_output.slew_mask = 0;
    return;
}

adcs_status_t status;
adcs_vec3_t cluster_momentum = {0,0,0};

// 2. Momentum Calculation
status = adcs_wheel_momentum(wo_input.wheels, 4, &cluster_momentum);
if (status != ADCS_OK || !adcs_is_finite_vec3(&cluster_momentum)) {
    wo_state.mode = WO_FAULT;
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0;
    wo_output.elapsed = 0;
    wo_output.recovery_count = 0;
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    for(int i=0; i<4; ++i) {
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = 0.0;
    }
    wo_output.momentum = cluster_momentum;
    wo_output.torque = (adcs_vec3_t){0,0,0};
    wo_output.momentum_norm = adcs_vec3_norm(&cluster_momentum);
    wo_output.predicted_trip_mask = 0;
    wo_output.saturation_mask = 0;
    wo_output.slew_mask = 0;
    return;
}

// 3. History Initialization
if (!wo_state.history_initialized) {
    for(int i=0; i<4; ++i) {
        wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
        wo_output.acceleration_rad_s2[i] = 0.0;
        wo_output.predicted_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
    }
    wo_state.history_initialized = 1;
    wo_output.momentum = cluster_momentum;
    wo_output.momentum_norm = adcs_vec3_norm(&cluster_momentum);
    wo_output.maximum_speed = 0.0;
    wo_output.predicted_maximum_speed = 0.0;
    wo_output.predicted_trip_mask = 0;
    wo_output.saturation_mask = 0;
    wo_output.slew_mask = 0;
    // State remains OFF (default)
    return; 
}

// 4. Prediction and Statistics
double max_abs_speed = 0.0;
double max_pred_abs_speed = 0.0;
unint32 pred_trip_mask = 0;

for(int i=0; i<4; ++i) {
    double current_speed = wo_input.wheels[i].speed_rad_s;
    double prev_speed = wo_state.previous_speed_rad_s[i];

    double accel = (current_speed - prev_speed) / wo_config.dt_s;
    wo_output.acceleration_rad_s2[i] = accel;

    double pred_speed = current_speed + accel * wo_config.prediction_horizon_s;
    wo_output.predicted_speed_rad_s[i] = pred_speed;

    double abs_curr = fabs(current_speed);
    double abs_pred = fabs(pred_speed);

    if (abs_curr > max_abs_speed) max_abs_speed = abs_curr;
    if (abs_pred > max_pred_abs_speed) max_pred_abs_speed = abs_pred;

    if (abs_pred >= wo_config.trip_rad_s) {
        pred_trip_mask |= (1U << i);
    }
}

wo_output.maximum_speed = max_abs_speed;
wo_output.predicted_maximum_speed = max_pred_abs_speed;
wo_output.predicted_trip_mask = pred_trip_mask;
wo_output.momentum = cluster_momentum;
wo_output.momentum_norm = adcs_vec3_norm(&cluster_momentum);

// 5. State Machine
wo_mode_t next_mode = wo_state.mode;
int has_trip = (pred_trip_mask != 0);

switch (wo_state.mode) {
    case WO_OFF:
        if (max_pred_abs_speed >= wo_config.warn_rad_s) {
            next_mode = WO_WATCH;
        }
        break;

    case WO_WATCH:
        if (has_trip) {
            next_mode = WO_ACTIVE;
        } else if (max_pred_abs_speed < wo_config.warn_rad_s) {
            next_mode = WO_OFF;
        }
        break;

    case WO_ACTIVE:
        if (wo_state.elapsed == 0) {
            wo_state.elapsed = 1;
        } else {
            wo_state.elapsed++;
        }

        if (wo_state.elapsed >= wo_config.minimum_active_cycles) {
            if (max_abs_speed <= wo_config.release_rad_s && max_pred_abs_speed <= wo_config.release_rad_s) {
                wo_state.clean++;
            } else {
                wo_state.clean = 0;
            }

            if (wo_state.clean >= wo_config.release_cycles) {
                next_mode = WO_RECOVERY;
            }
        }
        break;

    case WO_RECOVERY:
        if (has_trip) {
            next_mode = WO_ACTIVE;
        } else {
            if (wo_state.recovery_count == 0) {
                wo_state.recovery_count = 1;
            } else {
                wo_state.recovery_count++;
            }

            if (wo_state.recovery_count >= wo_config.recovery_cycles) {
                next_mode = WO_OFF;
            }
        }
        break;

    case WO_FAULT:
        break;
}

// 6. Control Law
adcs_vec3_t torque_out = {0,0,0};
unint32 sat_mask = 0;
unint32 slew_mask = 0;

if (next_mode == WO_ACTIVE) {
    adcs_vec3_t desired = adcs_vec3_scale(&cluster_momentum, -wo_config.gain);

    // Magnitude Limit
    adcs_actuator_limit_t mag_lim = {-wo_config.torque_limit, wo_config.torque_limit, 0.0};
    double vals[3] = {desired.x, desired.y, desired.z};
    for(int i=0; i<3; ++i) {
        double limited;
        if (adcs_limit_scalar(vals[i], &mag_lim, &limited) == ADCS_OK) {
            if (fabs(vals[i]) > wo_config.torque_limit) {
                sat_mask |= (1U << i);
            }
            vals[i] = limited;
        }
    }
    adcs_vec3_t limited = {vals[0], vals[1], vals[2]};

    // Slew Limit
    adcs_vec3_t delta = adcs_vec3_sub(&limited, &wo_state.previous_torque);
    double slew_mag = adcs_vec3_norm(&delta);
    double max_step = wo_config.torque_slew * wo_config.dt_s;

    if (slew_mag > max_step && slew_mag > FLT64_ZERO) {
        double scale = max_step / slew_mag;
        adcs_vec3_t scaled_delta = adcs_vec3_scale(&delta, scale);
        torque_out = adcs_vec3_add(&wo_state.previous_torque, &scaled_delta);
        slew_mask = 7U; // All axes affected by vector scaling
    } else {
        torque_out = limited;
    }

    wo_output.torque = torque_out;
    wo_output.saturation_mask = sat_mask;
    wo_output.slew_mask = slew_mask;

    wo_state.previous_torque = torque_out;
    for(int i=0; i<4; ++i) {
        wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
    }
} else {
    wo_output.torque = (adcs_vec3_t){0,0,0};
    wo_output.saturation_mask = 0;
    wo_output.slew_mask = 0;

    for(int i=0; i<4; ++i) {
        wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
    }
}

wo_output.mode = next_mode;
wo_state.mode = next_mode;

if (next_mode == WO_ACTIVE) {
    wo_state.elapsed = 0; // Reset for next cycle logic? No, logic above handles increment.
    // Wait, if I set elapsed=0 here, next call will see 0 and set to 1.
    // This effectively resets the count every time we enter ACTIVE.
    // Correct.
    wo_state.clean = 0;
}

if (next_mode == WO_RECOVERY) {
    wo_state.clean = 0;
    wo_state.recovery_count = 0;
}

