            wo_output.acceleration_rad_s2[i] = 0.0;
            wo_output.predicted_speed_rad_s[i] = 0.0;
        }
        wo_output.maximum_speed = 0.0;
        wo_output.predicted_maximum_speed = 0.0;
        return;
    }

    wo_output.momentum_norm = adcs_vec3_norm(&wo_output.momentum);

    // 2. History Initialization
    if (!wo_state.history_initialized) {
        for (int i = 0; i < 4; ++i) {
            wo_state.previous_speed_rad_s[i] = wo_input.wheels[i].speed_rad_s;
            wo_output.acceleration_rad_s2[i] = 0.0;
        }
        wo_state.history_initialized = 1;
    }

    // 3. Calculate Dynamics
    double dt_inv = 1.0 / wo_config.dt_s;
    double max_current_abs = 0.0;
    double max_predicted_abs = 0.0;
    uint32_t pred_trip_mask = 0U;

    for (int i = 0; i < 4; ++i) {
        double current_speed = wo_input.wheels[i].speed_rad_s;
        double prev_speed = wo_state.previous_speed_rad_s[i];
        double accel = (current_speed - prev_speed) * dt_inv;
        wo_output.acceleration_rad_s2[i] = accel;
        double predicted_speed = current_speed + accel * wo_config.prediction_horizon_s;
        wo_output.predicted_speed_rad_s[i] = predicted_speed;

        double abs_curr = fabs(current_speed);
        double abs_pred = fabs(predicted_speed);

        if (abs_curr > max_current_abs) max_current_abs = abs_curr;
        if (abs_pred > max_predicted_abs) max_predicted_abs = abs_pred;

        if (abs_pred >= wo_config.trip_rad_s) {
            pred_trip_mask |= (uint32_t)(1U << i);
        }
        wo_state.previous_speed_rad_s[i] = current_speed;
    }

    wo_output.maximum_speed = max_current_abs;
    wo_output.predicted_maximum_speed = max_predicted_abs;
    wo_output.predicted_trip_mask = pred_trip_mask;

    // 4. State Machine
    wo_mode_t next_mode = wo_state.mode;
    uint32_t clean = wo_state.clean;
    uint32_t elapsed = wo_state.elapsed;
    uint32_t recovery_count = wo_state.recovery_count;

    // Reset clean if not in Active or Recovery
    if (wo_state.mode != WO_ACTIVE && wo_state.mode != WO_RECOVERY) {
        clean = 0;
    }

    switch (wo_state.mode) {
        case WO_OFF:
            if (max_predicted_abs >= wo_config.warn_rad_s) {
                next_mode = WO_WATCH;
            } else if (max_predicted_abs >= wo_config.trip_rad_s) {
                next_mode = WO_ACTIVE;
                elapsed = 0;
                clean = 0;
            } else {
                next_mode = WO_OFF;
                clean = 0;
            }
            break;

        case WO_WATCH:
            if (max_predicted_abs < wo_config.warn_rad_s) {
                next_mode = WO_OFF;
            } else if (max_predicted_abs >= wo_config.trip_rad_s) {
                next_mode = WO_ACTIVE;
                elapsed = 0;
                clean = 0;
            } else {
                next_mode = WO_WATCH;
                clean = 0;
            }
            break;

        case WO_ACTIVE:
            elapsed++;
            int releasing = 0;
            if (elapsed >= wo_config.minimum_active_cycles) {
                if (max_current_abs <= wo_config.release_rad_s && 
                    max_predicted_abs <= wo_config.release_rad_s) {
                    releasing = 1;
                }
            }

            if (releasing) {
                clean++;
            } else {
                clean = 0;
            }

            if (clean >= wo_config.release_cycles) {
                next_mode = WO_RECOVERY;
                recovery_count = 0;
                clean = 0; // Will be reset by RECOVERY entry logic implicitly or explicitly
            } else {
                // Generate Torque
                adcs_vec3_t desired = adcs_vec3_scale(&wo_output.momentum, -wo_config.gain);
                double vals[3] = {desired.x, desired.y, desired.z};
                uint32_t sat_mask = 0;

                for (int k = 0; k < 3; ++k) {
                    if (vals[k] > wo_config.torque_limit) {
                        vals[k] = wo_config.torque_limit;
                        sat_mask |= (1U << k);
                    } else if (vals[k] < -wo_config.torque_limit) {
                        vals[k] = -wo_config.torque_limit;
                        sat_mask |= (1U << k);
                    } else {
                        // Within limits, no saturation
                    }
                }

                double slew_vals[3] = {vals[0], vals[1], vals[2]};
                uint32_t slew_mask = 0;
                for (int k = 0; k < 3; ++k) {
                    double prev_val = (k == 0) ? wo_state.previous_torque.x : 
                                      (k == 1) ? wo_state.previous_torque.y : 
                                                wo_state.previous_torque.z;
                    double delta = slew_vals[k] - prev_val;
                    double max_delta = wo_config.torque_slew * wo_config.dt_s;

                    if (delta > max_delta) {
                        slew_vals[k] = prev_val + max_delta;
                        slew_mask |= (1U << k);
                    } else if (delta < -max_delta) {
                        slew_vals[k] = prev_val - max_delta;
                        slew_mask |= (1U << k);
                    } else {
                        // Within slew limit, no change
                    }
                }

                wo_output.torque = (adcs_vec3_t){slew_vals[0], slew_vals[1], slew_vals[2]};
                wo_output.saturation_mask = sat_mask;
                wo_output.slew_mask = slew_mask;

                wo_state.previous_torque.x = slew_vals[0];
                wo_state.previous_torque.y = slew_vals[1];
                wo_state.previous_torque.z = slew_vals[2];
            }
            break;

        case WO_RECOVERY:
            if (pred_trip_mask != 0U) {
                next_mode = WO_ACTIVE;
                elapsed = 0;
                clean = 0;
            } else {
                recovery_count++;
                if (recovery_count >= wo_config.recovery_cycles) {
                    next_mode = WO_OFF;
                }
                wo_output.torque = (adcs_vec3_t){0, 0, 0};
                wo_output.saturation_mask = 0U;
                wo_output.slew_mask = 0U;
                wo_state.previous_torque.x = 0.0;
                wo_state.previous_torque.y = 0.0;
                wo_state.previous_torque.z = 0.0;
            }
            break;

        default:
            break;
    }

    wo_state.mode = next_mode;
    wo_state.clean = clean;
    wo_state.elapsed = elapsed;
    wo_state.recovery_count = recovery_count;
    wo_output.mode = wo_state.mode;
    wo_output.clean = clean;
    wo_output.elapsed = elapsed;
    wo_output.recovery_count = recovery_count;

